#!/bin/sh
# Fetch the Prometheus image of docker-compose.yaml by digest into images/ (generated by hydo
# compose; hydo-build never pulls). The Compose file's busybox exporter is the test client's own
# program in hydo.yaml, so its image is not fetched. Needs hydo-fetch-image (it comes with hydo)
# and network access, once. It fetches the image this machine builds: x86_64 on Linux, arm64 on a
# Mac. Name x86_64, arm64 or all as the argument to choose (sh fetch-images.sh all).
set -eu
cd "$(dirname "$0")"
A=${1:-}
[ -n "$A" ] || case "$(uname -s)" in Darwin) A=arm64;; *) A=x86_64;; esac
case "$A" in x86_64|arm64|all) ;; *) echo "fetch-images.sh: x86_64, arm64 or all (got $A)" >&2; exit 2;; esac
F=${HYDO_FETCH_IMAGE:-$(command -v hydo-fetch-image || true)}
[ -n "$F" ] || { echo "fetch-images.sh: hydo-fetch-image not found (put hydo's bin directory on PATH, or set HYDO_FETCH_IMAGE)" >&2; exit 1; }
mkdir -p images
[ "$A" = x86_64 ] || [ -e images/prom-prometheus-v3.16.0-arm64-oci ] || "$F" docker.io/prom/prometheus sha256:c523006440e714e0e53405b77e9f6ee668871d9855fc1c853fd43f5b990c34d2 prom/prometheus:v3.16.0 images/prom-prometheus-v3.16.0-arm64-oci
[ "$A" = arm64 ] || [ -f images/prom-prometheus-v3.16.0-amd64.docker.tar ] || "$F" docker.io/prom/prometheus sha256:89c1a644817e9ad70fa2af76c84898e327c1de7063735f962e8313b1e28672c3 prom/prometheus:v3.16.0 images/prom-prometheus-v3.16.0-amd64.docker.tar
[ "$A" = arm64 ] || ls -ld images/prom-prometheus-v3.16.0-amd64.docker.tar
[ "$A" = x86_64 ] || ls -ld images/prom-prometheus-v3.16.0-arm64-oci
